use crate::{editor::{Action,Editor},scene::Scene};
fn editor()->Editor{let mut e=Editor::default();e.apply(Action::Close).unwrap();e}
fn command(e:&mut Editor,line:&str)->Result<(),String>{let action=if let Some(a)=e.tool_line(line){a.map_err(str::to_owned)?}else{let crate::commands::Command::Editor(a)=crate::commands::parse(line)? else{return Err("Editor command".into())};a};e.apply(action).map_err(|message|if message=="Shape input invalid"{e.tool_status.clone()}else{message.into()})?;Ok(())}
#[test]
fn four_corners_keep_world_prefix_fixed_plane_guides_original_surface_and_one_undo(){
    let mut e=editor();command(&mut e,"CPlane XZ").unwrap();command(&mut e,"Nurbs Surface 4 Points").unwrap();for word in ["0,0","2,0","2,2,0.5"]{command(&mut e,word).unwrap()}e.apply(Action::ToolHover(Some([0.,0.,2.]))).unwrap();assert!(e.scene.objects().is_empty());let draft=e.draft.as_ref().unwrap();assert_eq!(draft.outlines()[0].len(),4);assert_eq!(draft.points.len(),3);command(&mut e,"0,2").unwrap();let s=e.scene.objects()[0].surface.as_ref().unwrap().source.clone();assert!(s.is_valid());assert_eq!(s.get_cv(0,0).unwrap(),session_rust::Point::new(0.,0.,0.));assert_eq!(s.get_cv(1,0).unwrap(),session_rust::Point::new(2.,0.,0.));let _=s.guid();let original=s.to_proto();let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut saved=Scene::empty();crate::scene_document::open(&mut saved,&bytes).unwrap();assert_eq!(saved.objects()[0].surface.as_ref().unwrap().source.to_proto(),original);command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());command(&mut e,"Redo").unwrap();assert_eq!(e.scene.objects()[0].surface.as_ref().unwrap().source.to_proto(),original);command(&mut e,"Nurbs Surface 4 Points w3,0,0 w4,0,0 w4,1,0 w3,1,0").unwrap();assert_eq!(e.scene.objects()[1].surface.as_ref().unwrap().source.get_cv(1,1).unwrap(),session_rust::Point::new(4.,1.,0.));
}
#[test]
fn invalid_initial_corner_count_and_degenerate_final_answer_keep_owner_and_redo(){
    let mut e=editor();command(&mut e,"Point w5,0,0").unwrap();command(&mut e,"Undo").unwrap();command(&mut e,"Curve").unwrap();command(&mut e,"w0,0,0").unwrap();assert!(command(&mut e,"Nurbs Surface 4 Points w0,0,0 w1,0,0 w2,0,0").is_err());assert_eq!(e.draft.as_ref().unwrap().tool.name(),"Curve");command(&mut e,"Escape").unwrap();command(&mut e,"Nurbs Surface 4 Points").unwrap();command(&mut e,"w0,0,0 w1,0,0 w2,0,0").unwrap();assert!(command(&mut e,"w3,0,0").is_err());assert_eq!(e.draft.as_ref().unwrap().points.len(),3);assert!(e.scene.objects().is_empty());command(&mut e,"Escape").unwrap();command(&mut e,"Redo").unwrap();assert_eq!(e.scene.points().len(),1);assert_eq!(crate::commands::canonical("nurbssurface_4_points"),"Nurbs Surface 4 Points");
}
#[test]
fn shuffled_placed_network_retains_original_lines_surface_archive_and_history(){
    let mut e=editor();for line in ["Line w0,1,0 w2,1,1","Line w2,0,0 w2,2,2","Line w2,0,0 w0,0,0","Line w1,0,0 w1,2,1","Line w0,2,0 w2,2,2","Line w0,0,0 w0,2,0"]{command(&mut e,line).unwrap()}let ids=e.scene.lines().iter().map(|r|r.id).collect::<Vec<_>>();let sources=e.scene.lines().iter().map(|r|r.prepared.source.clone()).collect::<Vec<_>>();for id in &ids{e.scene.place_following(*id,session_rust::Xform::translation(10.,0.,0.)).unwrap()}e.select_objects(ids,false);command(&mut e,"nurbsnurbs_network").unwrap();assert!(e.draft.is_none());let s=e.scene.objects()[0].surface.as_ref().unwrap().source.clone();let u=s.domain(0).unwrap();let v=s.domain(1).unwrap();let middle=s.point_at((u.0+u.1)/2.,(v.0+v.1)/2.).unwrap();assert!(middle.distance(&session_rust::Point::new(11.,1.,0.5),None)<1e-6);for(row,source)in e.scene.lines().iter().zip(sources){assert!(std::rc::Rc::ptr_eq(&row.prepared.source,&source))}let _=s.guid();let proto=s.to_proto();let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut saved=Scene::empty();crate::scene_document::open(&mut saved,&bytes).unwrap();assert_eq!(saved.objects()[0].surface.as_ref().unwrap().source.to_proto(),proto);assert_eq!(saved.lines().len(),6);command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());assert_eq!(e.scene.lines().len(),6);command(&mut e,"Redo").unwrap();assert_eq!(e.scene.objects().len(),1);assert_eq!(crate::commands::canonical("Nurbs Nurbs Network"),"Nurbs Surface Network");
}
#[test]
fn short_or_broken_network_keeps_ordered_picks_and_can_accept_more_curves(){
    let mut e=editor();for line in ["Line w0,0,0 w2,0,0","Line w0,1,0 w2,1,0","Line w0,0,0 w0,1,0","Line w2,0,0 w2,1,0"]{command(&mut e,line).unwrap()}let ids=e.scene.lines().iter().map(|r|r.id).collect::<Vec<_>>();command(&mut e,"Nurbs Surface Network").unwrap();e.apply(Action::GatherPick(Some(ids[0]))).unwrap();assert!(command(&mut e,"").is_err());e.apply(Action::GatherPick(Some(ids[1]))).unwrap();assert!(command(&mut e,"").is_err());assert_eq!(e.draft.as_ref().unwrap().gather.as_ref().unwrap().progress.rows[0],vec![ids[0].value(),ids[1].value()]);for id in &ids[2..]{e.apply(Action::GatherPick(Some(*id))).unwrap();}command(&mut e,"").unwrap();assert_eq!(e.scene.objects().len(),1);assert_eq!(e.scene.objects()[0].surface.as_ref().unwrap().source.degree(0),1);assert_eq!(e.scene.objects()[0].surface.as_ref().unwrap().source.degree(1),1);
}
